mapper.select:
SELECT id, user_id AS userId, mood_score AS moodScore, mood_desc AS moodDesc,
       record_time AS recordTime, remark
FROM mood_record WHERE user_id = #{userId}

mapper.update:
UPDATE mood_record
SET user_id=#{userId}, mood_score=#{moodScore}, mood_desc=#{moodDesc},
record_time=#{recordTime}, remark=#{remark}
WHERE id = #{id}

